package android.system; public class Os { public static java.util.List<String> calls=new java.util.ArrayList<>(); public static void rename(String a,String b)throws java.io.IOException {java.nio.file.Files.move(java.nio.file.Path.of(a),java.nio.file.Path.of(b),java.nio.file.StandardCopyOption.REPLACE_EXISTING);} public static void chmod(String p,int mode){if(mode!=0770)throw new AssertionError();calls.add(p);} }